<?php
header('Content-Type: text/html; charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];
$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function relp($p,$r){$x=realpath($p);return $x===false?'':ltrim(str_replace('\\','/',substr($x,strlen($r))),'/');}
function blockedp($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan_site($root){global $TEXT;$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$p=relp($f->getPathname(),$root);if($p===''||blockedp($p))continue;if($f->isDir())$dirs[$p]=1;elseif($f->isFile())$files[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];}ksort($files);ksort($dirs);$refs=[];$patterns=[
'/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i',
'/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i',
'/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i',
'/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];
foreach($files as $path=>$m){if(!$m['text']||$m['size']>700000)continue;$src=@file_get_contents($root.'/'.$path);if($src===false)continue;$found=[];foreach($patterns as $re){preg_match_all($re,$src,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v!==''&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$found[]=$v;}}foreach(array_unique($found) as $ref){$base=dirname($path);$candidate=ltrim(str_replace('\\','/',($ref[0]==='/'?$ref:$base.'/'.$ref)),'/');$vars=[$candidate,$candidate.'.php',$candidate.'.js',$candidate.'.css',$candidate.'.json',$candidate.'.html',$candidate.'/index.php',$candidate.'/index.html'];foreach($vars as $v)if(isset($files[$v])){$refs[]=['from'=>$path,'to'=>$v];break;}}}
return ['root'=>basename($root),'files'=>array_keys($files),'dirs'=>array_keys($dirs),'refs'=>$refs,'time'=>date('H:i:s'),'unix'=>microtime(true)];}
$data=scan_site($ROOT);
if(isset($_GET['data'])||isset($_GET['pulse'])){header('Cache-Control:no-store, no-cache, must-revalidate');header('Content-Type:application/json;charset=UTF-8');if(isset($_GET['pulse'])){echo json_encode(['ok'=>true,'time'=>$data['time'],'unix'=>$data['unix'],'files'=>count($data['files']),'links'=>count($data['refs'])]);}else echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — JARVIS Live File Map</title><style>
:root{--bg:#02060d;--panel:rgba(5,14,27,.88);--cyan:#24ddff;--cyan2:#65f5ff;--violet:#8f70ff;--green:#45f5b0;--text:#eaf7ff;--muted:#637693}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--text);font-family:Inter,system-ui,Segoe UI,Arial}body:before{content:"";position:fixed;inset:0;background-image:linear-gradient(rgba(40,100,150,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(40,100,150,.035) 1px,transparent 1px);background-size:44px 44px;pointer-events:none}#map{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:5;left:22px;right:22px;top:17px;display:flex;justify-content:space-between;pointer-events:none}.brand{pointer-events:auto}.ey{font:800 8px ui-monospace;letter-spacing:2px;color:#71839f}.ey b{color:var(--green);text-shadow:0 0 14px var(--green)}h1{font-size:30px;letter-spacing:-1.5px;margin:6px 0 2px}h1 span{color:var(--cyan);text-shadow:0 0 20px #24ddff55}.sub{font:8px ui-monospace;color:#52627d}.stats{display:flex;gap:6px}.stat{min-width:72px;padding:8px 10px;border:1px solid #6ea8d21c;border-radius:10px;background:var(--panel);backdrop-filter:blur(12px)}.stat small{display:block;font:700 7px ui-monospace;color:#596b87}.stat strong{font:800 12px ui-monospace}.live{color:var(--green)!important}.panel{position:fixed;z-index:6;right:20px;top:104px;width:285px;padding:14px;border:1px solid #6ea8d225;border-radius:13px;background:var(--panel);backdrop-filter:blur(16px);display:none}.panel.show{display:block}.k{font:800 7px ui-monospace;color:#647795;letter-spacing:1.3px}.panel h2{font-size:14px;margin:7px 0}.path{font:8px ui-monospace;color:#9cefff;word-break:break-all}.meta{font:8px ui-monospace;color:#7d8da8;line-height:1.8;margin-top:9px}.close{float:right;border:0;background:none;color:#72829d;font-size:17px}.tools{position:fixed;z-index:6;left:20px;bottom:17px;display:flex;gap:6px}.btn{padding:8px 11px;border:1px solid #6ea8d225;border-radius:8px;background:var(--panel);color:#b9c9de;font:800 8px ui-monospace;cursor:pointer}.btn:hover{border-color:#24ddff88;color:white}.search{position:fixed;z-index:6;left:20px;top:104px;width:235px;padding:10px;border:1px solid #6ea8d225;border-radius:9px;background:var(--panel);color:white;outline:0;font:800 9px ui-monospace;backdrop-filter:blur(12px)}.status{position:fixed;z-index:6;left:20px;bottom:55px;color:#52627d;font:700 7px ui-monospace}.pulse{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 15px var(--green);margin-right:6px}.load{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#02060df8}.loader{text-align:center}.loader i{display:block;width:54px;height:54px;border-radius:50%;border:2px solid #ffffff0d;border-top-color:var(--cyan);border-right-color:var(--violet);animation:spin .7s linear infinite;margin:auto}.loader b{display:block;margin-top:12px;font-size:11px}.loader small{display:block;margin-top:5px;color:var(--muted);font:8px ui-monospace}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:700px){.top{left:11px;right:11px;top:10px}h1{font-size:22px}.sub{display:none}.stats{gap:3px}.stat{min-width:49px;padding:6px}.stat small{font-size:6px}.stat strong{font-size:9px}.search{left:11px;top:76px;width:190px}.panel{left:11px;right:11px;top:76px;width:auto}.tools{left:11px;bottom:11px}.status{left:11px;bottom:48px}}
</style></head><body><div class="load" id="load"><div class="loader"><i></i><b>JARVIS NEURAL CORE</b><small id="lm">Scanning the live server filesystem…</small></div></div><div class="top"><div class="brand"><div class="ey"><b>●</b> SMARTTOOLZ / LIVE SYSTEM</div><h1>Full File <span>Mind Map</span></h1><div class="sub">LIVE SERVER • FILE DEPENDENCIES • NEURAL ACTIVITY</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="fc">0</strong></div><div class="stat"><small>LINKS</small><strong id="ec">0</strong></div><div class="stat"><small>PULSES</small><strong id="pc">0</strong></div><div class="stat"><small>STATE</small><strong id="st" class="live">LIVE</strong></div></div></div><input class="search" id="search" placeholder="Search file / folder…"><canvas id="map"></canvas><div class="panel" id="panel"><button class="close" id="close">×</button><div class="k">NEURAL NODE</div><h2 id="pn"></h2><div class="path" id="pp"></div><div class="meta" id="pm"></div></div><div class="status"><span class="pulse"></span>SERVER HEARTBEAT <b id="hb">CONNECTING</b></div><div class="tools"><button class="btn" id="fit">FIT MAP</button><button class="btn" id="pause">PAUSE</button><button class="btn" id="rescan">RESCAN</button></div>
<script>
const initial=<?php echo json_encode($data,JSON_UNESCAPED_SLASHES); ?>;const cv=document.getElementById('map'),g=cv.getContext('2d');let W,H,dpr=1,nodes=[],edges=[],sel=null,hover=null,zoom=1,ox=0,oy=0,drag=false,lastX=0,lastY=0,paused=false,pulses=0,serverAlive=false;
function size(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;g.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',size);size();
function build(D){nodes=[];edges=[];const folders=new Map();D.dirs.forEach(p=>folders.set(p,{id:'d:'+p,path:p,name:p.split('/').pop()+'/',folder:1,x:0,y:0,r:8}));D.files.forEach(p=>nodes.push({id:'f:'+p,path:p,name:p.split('/').pop(),folder:0,x:0,y:0,r:3.2}));nodes=[...folders.values(),...nodes];const m=new Map(nodes.map(n=>[n.id,n]));for(const n of nodes)if(n.folder&&n.path.includes('/')){const par=n.path.split('/').slice(0,-1).join('/');if(m.has('d:'+par))edges.push({a:m.get('d:'+par),b:n,type:'tree',phase:Math.random()*6});}for(const n of nodes)if(!n.folder&&n.path.includes('/')){const par=n.path.split('/').slice(0,-1).join('/');if(m.has('d:'+par))edges.push({a:m.get('d:'+par),b:n,type:'tree',phase:Math.random()*6});}const seen=new Set();for(const r of D.refs){const a=m.get('f:'+r.from),b=m.get('f:'+r.to');if(a&&b){const k=a.id+'>'+b.id;if(!seen.has(k)){seen.add(k);edges.push({a,b,type:'dep',phase:Math.random()*6})}}}layout();document.getElementById('fc').textContent=D.files.length;document.getElementById('ec').textContent=D.refs.length;}
function layout(){const cx=W/2,cy=H/2;const roots=nodes.filter(n=>n.folder&&!n.path.includes('/'));const groups=new Map(roots.map(r=>[r.path,[]]));nodes.filter(n=>!n.folder).forEach(n=>{const root=n.path.split('/')[0];if(groups.has(root))groups.get(root).push(n)});roots.forEach((r,i)=>{const a=i/Math.max(1,roots.length)*Math.PI*2-Math.PI/2;const rr=Math.min(W,H)*.27;r.x=cx+Math.cos(a)*rr;r.y=cy+Math.sin(a)*rr;const kids=groups.get(r.path)||[];kids.forEach((n,j)=>{const span=Math.min(1.65,Math.max(.65,kids.length*.035));const aa=a-span/2+(j/Math.max(1,kids.length-1))*span;const rad=Math.min(W,H)*(.10+Math.min(.15,kids.length*.0009));n.x=r.x+Math.cos(aa)*rad;n.y=r.y+Math.sin(aa)*rad;});});const loose=nodes.filter(n=>!n.folder&&!groups.has(n.path.split('/')[0]));loose.forEach((n,i)=>{const a=i/Math.max(1,loose.length)*Math.PI*2;n.x=cx+Math.cos(a)*Math.min(W,H)*.4;n.y=cy+Math.sin(a)*Math.min(W,H)*.4});}
function pos(n){return{x:n.x*zoom+ox,y:n.y*zoom+oy}}function connected(n){return sel&&edges.some(e=>(e.a===n&&e.b===sel)||(e.b===n&&e.a===sel))}
function draw(t){g.clearRect(0,0,W,H);const dep=edges.filter(e=>e.type==='dep');for(const e of edges){const a=pos(e.a),b=pos(e.b),hot=e.a===sel||e.b===sel||e.a===hover||e.b===hover;g.beginPath();g.moveTo(a.x,a.y);g.lineTo(b.x,b.y);g.strokeStyle=hot?'rgba(36,221,255,.8)':e.type==='dep'?'rgba(36,221,255,.18)':'rgba(143,112,255,.075)';g.lineWidth=hot?2:e.type==='dep'?1:.5;g.stroke();if(e.type==='dep'&&!paused){const q=(t/1900+e.phase)%1,px=a.x+(b.x-a.x)*q,py=a.y+(b.y-a.y)*q;g.beginPath();g.arc(px,py,2.4+Math.sin(t/130+e.phase)*.7,0,Math.PI*2);g.fillStyle='#45f5b0';g.shadowBlur=16;g.shadowColor='#45f5b0';g.fill();g.shadowBlur=0;}}
let active=0;for(const n of nodes){const p=pos(n),hot=n===sel||n===hover||connected(n);if(hot)active++;const rr=(n.r+(hot?2:0))*Math.max(.7,Math.min(1.8,zoom));g.beginPath();g.arc(p.x,p.y,rr,0,7);g.fillStyle=n.folder?'#8f70ff':hot?'#65f5ff':'#102238';g.shadowBlur=hot?18:5;g.shadowColor=n.folder?'#8f70ff':'#24ddff';g.fill();g.shadowBlur=0;if(zoom>.72||hot){g.fillStyle=hot?'#eafcff':'#657795';g.font=(hot?'9':'7')+'px ui-monospace';g.fillText(n.name,p.x+rr+4,p.y+3)}}document.getElementById('pc').textContent=pulses;requestAnimationFrame(draw)}
function hit(mx,my){let best=null,bd=18;for(const n of nodes){const p=pos(n),d=Math.hypot(mx-p.x,my-p.y);if(d<bd){bd=d;best=n}}return best}
cv.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY;cv.classList.add('drag')};addEventListener('pointermove',e=>{if(drag){ox+=e.clientX-lastX;oy+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY}hover=hit(e.clientX,e.clientY)});addEventListener('pointerup',e=>{drag=false;cv.classList.remove('drag');const n=hit(e.clientX,e.clientY);if(n){sel=n;document.getElementById('panel').classList.add('show');document.getElementById('pn').textContent=n.name;document.getElementById('pp').textContent=n.path;const links=edges.filter(z=>z.a===n||z.b===n);document.getElementById('pm').textContent=(n.folder?'FOLDER':'FILE')+' • '+links.length+' local links • '+links.filter(z=>z.type==='dep').length+' code dependencies'}});cv.onwheel=e=>{e.preventDefault();zoom=Math.max(.25,Math.min(4,zoom*Math.exp(-e.deltaY*.001)))};
document.getElementById('close').onclick=()=>document.getElementById('panel').classList.remove('show');document.getElementById('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'PLAY':'PAUSE';document.getElementById('st').textContent=paused?'PAUSED':'LIVE'};document.getElementById('fit').onclick=()=>{zoom=1;ox=0;oy=0;layout()};document.getElementById('rescan').onclick=()=>location.href=location.pathname+'?data=1';document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){sel=null;return}const n=nodes.find(n=>n.path.toLowerCase().includes(q));if(n){sel=n;ox=W/2-n.x*zoom;oy=H/2-n.y*zoom;document.getElementById('panel').classList.add('show');document.getElementById('pn').textContent=n.name;document.getElementById('pp').textContent=n.path}};addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r'){zoom=1;ox=0;oy=0;layout()}});
async function heartbeat(){try{const r=await fetch(location.pathname+'?pulse=1&_='+Date.now(),{cache:'no-store'});const d=await r.json();if(d.ok){serverAlive=true;pulses++;document.getElementById('hb').textContent=d.time;document.getElementById('st').textContent='LIVE'}}catch(e){serverAlive=false;document.getElementById('hb').textContent='OFFLINE';document.getElementById('st').textContent='OFFLINE'}setTimeout(heartbeat,2000)}
build(initial);document.getElementById('load').style.display='none';heartbeat();requestAnimationFrame(draw);
</script></body></html>